-- =====================================================================================
-- Tibia Map - database step 33: AI drafts of quest guides from the TibiaWiki walkthroughs (slice 13j)
--
-- Run this once in Supabase (the house planner's project): SQL Editor -> New query -> paste everything -> Run.
-- Needs steps 3, 6, 7 and 9. Written by tools/drafts-to-sql.js from tools/data/quest-drafts. Every step is a draft
-- (not checked) with its wiki sentence as its source; what the checker couldn't tie to a real NPC, word, monster,
-- item or spot is a Note "Needs placing: ...". The quest's Reward steps from the old spots are moved into the draft.
-- Earlier drafts of these quests are replaced; a quest with anything made, changed or ticked in the app is skipped.
--
-- 25 steps for 1 quests (0 need placing):
--   The Queen of the Banshees Quest: 9 parts, 25 steps + 0 Reward steps
--       no Warlock spawns within 12 tiles of 32213,31847,15
--       can't walk 32219,31844,15 -> 32172,31858,15 (On through the caves: 2 giant spiders to the north, use your pick on the marked spot and go down; up again into a cave with lots of demon skeletons. (A rope spot in its middle leads to the Isle of the Kings' catacombs: the quickest way out from here.) Pick again to reach the seal room.): No route found: these two places are not connected.
-- =====================================================================================

-- The Queen of the Banshees Quest
do $$
declare seg bigint; new_segs bigint[] := '{}'; sort_now integer;
begin
  if exists (select 1 from public.map_quest_steps where quest_id = 86 and (source is null or updated_by is not null or checked)) then return; end if;
  delete from public.map_quest_steps where quest_id = 86 and source <> 'old quest spot';
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 10, 'The way in') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'note', 'Level 60 (the queen won''t kiss you below it). Bring a rope, a pick, a vial of blood and one black and one white pearl. Do the seals in the order of this guide: it''s the quickest, though their numbers say otherwise. If you stop at a seal you have to walk back; after the queen''s kiss you''re teleported out.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Needed: Rope, Pick, Blood (any container with blood works), 1 Black Pearl and 1 White Pearl. The quickest way to complete this quest is to do the seals out of order. If you decide to stop at any seal, you''ll have to go back the way you came.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'go', 'In the Ghostlands, go down this hole.', 32223, 31860, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'First go to the Ghostlands and go down a hole (Mapper Coords 125.223, 124.117, 7)');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 30, 'go', 'South and down the next hole (skeletons, ghouls, poison spiders), then south-east and down again, to the two magic walls east of the rope spot. Two switches open them: one to the west, one to the east.', 32258, 31892, 10, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go south and go down a hole. Go south-east and go the hole down. Go to the Magic Walls east from the rope spot. To open the Magic Walls you need to use 2 switches. There is 1 switch west of here and 1 switch east of here.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 40, 'kill', 'East switch: kill the giant spider guarding it and pull the switch. Alone, do this one first.', 32314, 31911, 12, null, 'Giant Spider', '[]'::jsonb, null, '[]'::jsonb, false, 'The east switch is guarded by a Giant Spider. TIP: Start with the east switch if you go alone then the west switch');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 50, 'go', 'West switch: through scorpions, 3 demon skeletons and ghouls; in the switch room 2 bonelords, a demon skeleton, stalkers and ghouls. Pull the switch, then haste back to the walls.', 32212, 31888, 12, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'To get to the west switch you have to go through many scorpions, 3 demon skeletons and some ghouls and then in the switch room there are 2 Bonelords, 1 Demon Skeleton, 2-3 Stalkers and Ghouls.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 60, 'go', 'Through where the magic walls were, all together: hidden buttons just past them close the walls again. Go down the hole (the teleporter there leads back if the walls closed).', 32259, 31891, 10, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'remember to use haste from the first switch when it has been pulled because the walls close when anyone steps on the hidden buttons. After the Magic Walls, go down the hole. (The teleporter is for going back if the Magic Walls have closed.)');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 70, 'go', 'Walk north through the room (mummies, ghosts, demon skeletons, stalkers). Walk over the poison fields around the stone: a switch appears. Pull it to reveal stairs. (The body at the top of the room holds Brother Fugio''s diary for the White Raven Monastery Quest.)', 32266, 31861, 11, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Walk north in this room. Here are mummies, ghosts, demon skeletons and stalkers. You can open the body on the top of the room to get some junk and a book... You will see a stone surrounded by poison fields. Walk over the poison fields and a switch will appear beneath it. Use the switch to reveal some stairs.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 80, 'go', 'Down the stairs and through the teleporter.', 32266, 31857, 12, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go down the stairs and go through the teleporter (A).');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 90, 'go', 'Go south in the long hall and use your pick in the middle of it (going on to the end teleports you back). Go down the hole.', 32266, 31900, 12, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go south in this long hall and use your pick in the middle of the hall. If you simply keep going south, you will be teleported back. Go down the pick hole to find the first seal room.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 20, 'The Hidden Seal') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'go', 'Everyone goes through the blue flame: each one summons 2 ghosts and a demon skeleton. You land in a small room: its teleporter brings you back.', 32278, 31903, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'In this room, you will see a blue flame. Every party member must go through the flame, and for every party member that goes through, 2 ghosts and a demon skeleton will be summoned. After going through the flame you will be teleported into a small room with another teleporter. Go through it to go back to the first seal room.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 30, 'The Seal of Logic') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'go', 'Go south and rope yourself up, then on south. At the end go west, up the ramp and down into a round chamber (3 ghosts, 3 stalkers, 4 demon skeletons). Go down the stairs.', 32254, 31942, 12, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go south, rope yourself up and then continue south. At the end, go west, up the ramp and down into a round chamber. In this room are 3 Ghosts, 3 Stalkers and 4 Demon Skeletons. Go down the stairs.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'go', 'Walk as far south-east as you can (ghosts, stalkers, demon skeletons, many scorpions). Set the six switches as in the wiki''s picture, then through the flame and back through the teleporter. One player setting them is enough.', 32312, 31974, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Walk as far to the south-east and you will come to the second seal. You will have to go through: Ghosts, Stalkers, Demon Skeleton and many Scorpions. You need to organize the switches so the match the second image. Then go through the flame and back through teleporter. Only one person needs to do this for the others to go through.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 40, 'The Seal of the True Path') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'note', 'Back to the stairs in the north-west of this floor and down (ghosts). On the way to the next stairs are 10 banshees, never more than 3 at a time; a quest door on the way hides the Spectral Dress (Explorer Society Quest).', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Backtrack to the stairs at the north-west part this floor. Go down to be faced by ghosts. On the way you will encounter 10 banshees. Keep in mind that you''ll never face more than 3 at a time in this area. On the way, you will find a quest door which conceals a box with the Spectral Dress.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'go', 'North-west up the stairs (one more banshee). Walk over the stone tiles in the pattern of the wiki''s picture, then through the flame and back through the teleporter.', 32186, 31938, 14, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go north-west to the stairs. Careful as you''ll encounter another banshee. Go up and walk on the tiles as shown on the second image. Go through the flame and back through the teleporter.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 50, 'The Seal of Sacrifice') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'note', 'Go back down and take the stairs to the north, up into a room with 5 ghosts, 5 stalkers and 2 demon skeletons. Down the other stairs and follow the way to the next stairs: a room with poison fields, ghosts and demon skeletons.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go back down and go to the stairs north from here. Go up into the room where you''ll find 5 ghosts, 5 stalkers and 2 demon skeletons. Go down the other stairs, and just follow the way to the next stairs. The next room will be filled with poison fields, Ghosts and Demon Skeletons.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'go', 'Up the stairs and north through the room. In its north corner: spill the vial of blood on the tile between the two sacrificial stones. Then through the flame and back through the teleporter.', 32244, 31892, 14, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Going up the stairs, walk north through this room. In the north corner of this room lies the forth seal. Use the vial and spill the blood between the two stones (on the tile that looks like the depot tiles). Go through the flame and back through the teleporter.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 60, 'The Seal of Demonrage') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'kill', 'Through the stairs in the blood room and on. In the tight corridor to the south, stepping on one of the two special tiles summons 2 warlocks per player (one in the corridor, one in the room below). Every player must step on one. Kill them: a blocker keeps one busy below while the team kills the other.', 32213, 31847, 15, null, 'Warlock', '[]'::jsonb, null, '[]'::jsonb, false, 'For every person in your party, you will face 2 warlocks. In the tight corridor to the south, you will see 2 special tiles... After stepping on either one, you will spawn the 2 warlocks.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'go', 'Each player pulls the five switches in the order of the wiki''s picture and goes through the fire. Solo, you can ignore the warlocks and pull the switches while healing.', 32219, 31844, 15, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'After the whole team has stepped on a tile, each person must pull the switches in the order as shown below and proceed through the fire. An alternative strategy if you solo this part is just ignore them and pull the switches while constantly healing.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 70, 'The Plague Seal') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'go', 'On through the caves: 2 giant spiders to the north, use your pick on the marked spot and go down; up again into a cave with lots of demon skeletons. (A rope spot in its middle leads to the Isle of the Kings'' catacombs: the quickest way out from here.) Pick again to reach the seal room.', 32172, 31858, 15, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go north (you will face 2 Giant Spiders), after that use pick on the place marked in the map and you will go down. Go up, there will be a lot of demon skeleton. Go from A to B and use pick to get access to the sixth seal room. Note: you will pass by a rope spot, this leads to the catacombs of the Isle Of The Kings.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'go', 'Put the white pearl on the left stone and the black pearl on the right one, and go through a teleporter (left or right). Head north through the poison fields to the teleporter at the end, then the one in the room you arrive in, then the teleporters behind the pearls back.', 32176, 31863, 15, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'place the pearls where the picture shows and pass through the teleport. After you have walked through a teleport, head north through a couple of poison fields and walk through the teleport which you find at the end of the way. In the room where you now arrive, walk through the teleport which you see there.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 80, 'The Kiss of the Banshee Queen') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'kill', 'The queen is close to the Seal of Sacrifice. Kill the banshees (4), mummies, ghosts and stalkers around her.', 32254, 31863, 14, null, 'Banshee', '[]'::jsonb, null, '[]'::jsonb, false, 'Go to The Queen Of The Banshee (it''s close to seal #4), she is surrounded by 4 banshees, 2 mummies, 2 ghosts and 3 stalkers');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'talk', 'Ask the queen for the seventh seal: she checks your six seals, then gives you her kiss. You''re teleported to a small room; go up the stairs to the Ghostlands.', null, null, null, 'The Queen of the Banshee', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Be greeted, dear visitor. Come and stay ... a while."},{"say":"seventh","reply":"If you have passed the first six seals and entered the blue fires that lead to the chamber of the seal you might receive my kiss ... It will open the last seal. Do you think you are ready?","cond":["level 60+"],"alts":[{"cond":["below level 60"],"reply":"You are not experienced enough to master the challenges ahead or to receive knowledge about the seventh seal. Go and learn more before asking me again."}]},{"say":"yes","reply":"Yessss, I can sense you have passed the seal of sacrifice. Have you passed any other seal yet?","cond":["quest 4 is 1"],"alts":[{"cond":["quest 4 below 1"],"reply":"You have not passed the seal of sacrifice yet. Return to me when you are better prepared."}]},{"say":"yes","reply":"I sense you have passed the hidden seal as well. Have you passed any other seal yet?","cond":["quest 5 is 1"],"alts":[{"cond":["quest 5 below 1"],"reply":"You have not found the hidden seal yet. Return when you are better prepared."}]},{"say":"yes","reply":"Oh yes, you have braved the plagueseal. Have you passed any other seal yet?","cond":["quest 6 is 1"],"alts":[{"cond":["quest 6 below 1"],"reply":"You have not faced the plagueseal yet. Return to me when you are better prepared."}]},{"say":"yes","reply":"Ah, I can sense the power of the seal of demonrage burning in your heart. Have you passed any other seal yet?","cond":["quest 7 is 1"],"alts":[{"cond":["quest 7 below 1"],"reply":"You are not filled with the fury of the imprisoned demon. Return when you are better prepared."}]},{"say":"yes","reply":"So, you have managed to pass the seal of the true path. Have you passed any other seal yet?","cond":["quest 9 is 1"],"alts":[{"cond":["quest 9 below 1"],"reply":"You have not found your true path yet. Return when you are better prepared."}]},{"say":"yes","reply":"I see! You have mastered the seal of logic. You have made the sacrifice, you have seen the unseen, you possess fortitude, you have filled yourself with power and found your path. You may ask me for my kiss now.","cond":["quest 10 is 1"],"alts":[{"cond":["quest 10 below 1"],"reply":"You have not found your true path yet. Return to meh when you are better prepared."}]},{"say":"kiss","reply":"Are you prepared to receive my kiss, even though this will mean that your death as well as a part of your soul will forever belong to me, my dear?","cond":["quest 11 below 1"]},{"say":"yes","reply":"So be it! Hmmmmmm...","fx":["quest 11 becomes 1","quest 12 becomes quest 12+1","teleports you to 32202, 31812, 8"]}]'::jsonb, false, 'After clearing all of the banshees around the Queen talk to her and say: Hi, Seventh Seal, Yes x6, Kiss, Yes. You will then be teleported to a small room. Go up the stairs and you''ll be in the surface of Ghostlands again.');
  insert into public.map_quest_segments (quest_id, sort, name) values (86, 90, 'The final room') returning id into seg;
  new_segs := new_segs || seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 10, 'go', 'Come all the way back from the Ghostlands (or via the Isle of the Kings) to the stairs west of the queen. Bring 280-300 free cap. Once down, you can''t go up again.', 32219, 31893, 14, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'The final room is west of the Banshee Queen, you need to get there again all the way from the Ghostlands, it''s also possible to go via the Isle of the Kings. Prepare 280-300 extra cap for rewards. Once you go downstairs you can''t go up again.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 20, 'kill', 'Kill the banshees, dragon lords and giant spiders (lure them if you can).', 32219, 31898, 15, null, 'Banshee', '[]'::jsonb, null, '[]'::jsonb, false, 'The final room contains 6 Banshees, 2 Dragon Lords and 2 Giant Spiders, usually you have to lure them. Kill everything, and grab your rewards.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (86, seg, 30, 'reward', 'The chests: Boots of Haste, Giant Sword, Tower Shield, Stealth Ring, Stone Skin Amulet and 100 platinum coins. Take everything: once you leave through the magic forcefield you can''t come back. It puts you on the Ghostlands surface.', 32212, 31896, 15, null, null, '[[3079,1],[3281,1],[3428,1],[3049,1],[3081,1],[3035,100]]'::jsonb, 2472, '[]'::jsonb, false, 'Once you Leave the room (walked through the Magic Forcefield), you can''t enter again. So be sure to grab all the rewards. After entering the Magic Forcefield you will be teleported to the Ghostlands surface.');
  update public.map_quest_steps st set segment_id = seg, sort = 30 + r.n * 10 from (select id, row_number() over (order by sort, id) n from public.map_quest_steps where quest_id = 86 and source = 'old quest spot') r where st.id = r.id;
  select coalesce(max(sort), 30) into sort_now from public.map_quest_steps where segment_id = seg;
  delete from public.map_quest_segments s where s.quest_id = 86 and not (s.id = any(new_segs))
    and not exists (select 1 from public.map_quest_steps t where t.segment_id = s.id);
end $$;
